/**
 * Ambient type declarations for jspdf-autotable
 * 
 * jspdf-autotable doesn't have a separate @types package - it extends
 * jsPDF via module augmentation. This file provides the necessary type
 * declarations for the lastAutoTable property added to jsPDF instances.
 */

import type { jsPDF as JsPDFType } from "jspdf";
import type { Table, Column as AutoTableColumn } from "jspdf-autotable";

// Augment jsPDF to include the autoTable method and lastAutoTable property
declare module "jspdf" {
  interface jsPDF {
    /**
     * Adds a table to the PDF document.
     * 
     * @param options Configuration for the table appearance and content
     * @returns The current jsPDF instance for chaining
     */
    autoTable(options: {
      /** Table header rows */
      head?: any[][];
      /** Table body rows */
      body?: any[][];
      /** Columns configuration */
      columns?: AutoTableColumn[] | ((data: { doc: jsPDF }) => AutoTableColumn[]);
      /** Starting Y position */
      startY?: number;
      /** Table configuration */
      tableWidth?: number | "auto" | "wrap";
      /** Column widths */
      columnWidth?: "auto" | number | "wrap" | { [key: string]: number | "auto" };
      /** Row height */
      rowHeight?: number | ((data: { cell: any; row: number; column: number }) => number);
      /** Theme configuration */
      theme?: "striped" | "grid" | "horizontal" | "plain" | { [key: string]: any };
      /** Styles applied to header row */
      headStyles?: {
        fillColor?: any;
        textColor?: any;
        fontStyle?: "normal" | "bold" | "italic" | "bolditalic";
        fontSize?: number;
        halign?: "left" | "center" | "right";
        valign?: "top" | "middle" | "bottom";
      };
      /** Styles applied to body rows */
      bodyStyles?: {
        fillColor?: any;
        textColor?: any;
        fontStyle?: "normal" | "bold" | "italic" | "bolditalic";
        fontSize?: number;
        halign?: "left" | "center" | "right";
        valign?: "top" | "middle" | "bottom";
      };
      /** Styles applied to footer row */
      footStyles?: {
        fillColor?: any;
        textColor?: any;
        fontStyle?: "normal" | "bold" | "italic" | "bolditalic";
        fontSize?: number;
        halign?: "left" | "center" | "right";
        valign?: "top" | "middle" | "bottom";
      };
      /** Column-specific styles */
      columnStyles?: {
        [key: number | string]: {
          cellWidth?: number | "auto" | "wrap";
          halign?: "left" | "center" | "right";
          valign?: "top" | "middle" | "bottom";
          fontStyle?: "normal" | "bold" | "italic" | "bolditalic";
          fontSize?: number;
          fillColor?: any;
          textColor?: any;
        };
      };
      /** Margin configuration */
      margin?: {
        top?: number;
        right?: number;
        bottom?: number;
        left?: number;
      };
      /** Overflow handling */
      overflow?: "linebreak" | "ellipsize" | "truncation" | "visible";
      /** Page break handling */
      pageBreak?: "auto" | "avoid" | "always" | "anywhere";
      /** Table header */
      tableHeader?: any;
      /** Table footer */
      tableFooter?: any;
      /** Show footers on all pages */
      showFootlines?: boolean;
      /** Processing hooks */
      didParseCell?: (data: { cell: any; row: number; column: number }) => void;
      willSaveCell?: (data: { cell: any; row: number; column: number }) => void;
      didSaveCell?: (data: { cell: any; row: number; column: number }) => void;
      didAddPage?: (data: { pageCount: number }) => void;
      willDrawCell?: (data: { cell: any; row: number; column: number }) => void;
      didDrawCell?: (data: { cell: any; row: number; column: number }) => void;
      willPrintPage?: (data: { pageCount: number }) => void;
      didPrintPage?: (data: { pageCount: number }) => void;
    }): JsPDFType;

    /**
     * Contains the last table generated by autoTable.
     * Available immediately after calling autoTable.
     */
    lastAutoTable?: {
      /** Final Y position after the table */
      finalY: number;
      /** The table object */
      table: Table;
      /** Pages created during table generation */
      pages: number[];
    };
  }
}

export {};